class Customer:
    def __init__(self, name): self.name, self._roles = name, {}
    def add_role(self, role_type):
        return self._roles.setdefault(role_type, role_type(self))   # core creates its roles
class CustomerRole:                    # wraps the core and forwards core operations
    def __init__(self, core): self.core = core
    def __getattr__(self, name):       # reached only when the role lacks the attribute
        return getattr(self.core, name)
class BorrowerRole(CustomerRole):
    def borrow(self, amount): return f"{self.name} borrows {amount}"
